// 🤖 GENERACIÓN CONTENIDO COACHING PERSONAL MULTIIDIOMA
// 12 signos × 6 idiomas = 72 contenidos de coaching diarios

const zodiacSigns = [
  'Aries', 'Tauro', 'Géminis', 'Cáncer', 'Leo', 'Virgo',
  'Libra', 'Escorpio', 'Sagitario', 'Capricornio', 'Acuario', 'Piscis'
];

const languages = [
  { code: 'es', name: 'Spanish' },
  { code: 'en', name: 'English' },
  { code: 'de', name: 'German' },
  { code: 'fr', name: 'French' },
  { code: 'it', name: 'Italian' },
  { code: 'pt', name: 'Portuguese' }
];

// Crear todas las combinaciones signo-idioma
const combinations = [];
for (const sign of zodiacSigns) {
  for (const lang of languages) {
    combinations.push({
      sign: sign,
      languageCode: lang.code,
      languageName: lang.name,
      id: `${sign}_${lang.code}`,
      date: new Date().toISOString().split('T')[0],
      contentType: 'cosmic_coaching'
    });
  }
}

console.log(`🤖 Generando ${combinations.length} contenidos de coaching cósmico`);

return combinations.map(combo => ({
  json: combo
}));

const items = $input.all();
const prepItems = $("Prepare Cosmic Coaching Content").all(); // accedemos a los 72 datos originales
const results = [];

for (let i = 0; i < items.length; i++) {
  const input = items[i].json;
  const chatResponse = input.message?.content || input.choices?.[0]?.message?.content || "{}";
  const prep = prepItems[i]?.json || {};

  try {
    const jsonMatch = chatResponse.match(/{[\s\S]*}/);
    const coachingData = jsonMatch ? JSON.parse(jsonMatch[0]) : {};

    const finalJson = {
      sign: prep.sign || "Unknown",
      language_code: prep.languageCode || "es",
      date: prep.date || new Date().toISOString().split("T")[0],
      coaching_focus: coachingData.coaching_focus || "Enfoque del Día",
      ai_insight: coachingData.ai_insight || "Análisis astrológico general.",
      content: coachingData.content || "Contenido de coaching no disponible.",
      rating: coachingData.rating || 4,
      lucky_numbers: coachingData.lucky_numbers || [5, 10, 25],
      lucky_colors: coachingData.lucky_colors || ["plata", "índigo"],
      advice: coachingData.advice || "Sigue tu intuición y brilla.",
      content_type: coachingData.content_type || "cosmic_coaching",
      generated_at: prep.date || new Date().toISOString().split("T")[0]
    };

    results.push({ json: finalJson });

  } catch (error) {
    results.push({
      json: {
        error: "Error processing AI response",
        errorMessage: error.message,
        originalResponse: chatResponse
      }
    });
  }
}

return results;
